type Row = readonly [date: string, description: string, kobo: number];
type Parsed = readonly [error: string, row: null] | readonly [error: null, row: Row];

function parseRow(line: string): Parsed {
  const cells = line.split(",").map((cell) => cell.trim());
  if (cells.length !== 3) return ["invalid", null];
  const [date, description, amount] = cells;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return ["invalid", null];
  const naira = Number(amount);
  if (amount === "" || !Number.isFinite(naira)) return ["invalid", null];
  return [null, [date, description, Math.round(naira * 100)]];
}

for (const line of ["2026-09-01,Airtime,-500.50", "2026-09-02,Rent", "2026-09-03,Refund,", "09/2026,Lunch,-20"]) {
  const [error, row] = parseRow(line);
  console.log(error === null ? row.join(" | ") : error);
}

